export function findBuiltIn(query) {
  const needle = query.trim().toLowerCase();
  if (!needle) return BUILT_IN_PLANTS;
  return BUILT_IN_PLANTS.filter((plant) =>
    `${plant.commonName} ${plant.scientificName} ${plant.family ?? ''}`.toLowerCase().includes(needle),
  );
}
